-- Passage rg3-story-details-inference-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('8df75e0e-e004-5424-8369-eae2b22a9257', 'rg3-story-details-inference-p07', (select id from public.skills where slug = 'read-g3-story-details-inference'), null,
        '3-5', $q$Three Turns Too Many$q$, $q$Ayesha and Ben built a small robot for the school science fair. It had two wheels, a blinking light, and a tiny computer for a brain. They wrote a program that told the robot to roll forward, turn left, and stop at a paper finish line.

On the first test, the robot rolled forward perfectly. Then it spun in a circle three times and crashed into a chair leg.

"Maybe the batteries are low," Ben said. They put in new batteries. The robot spun in circles again.

Ayesha sat down with the laptop and read the program one line at a time. Each line was a step for the robot to follow. Near the bottom, Ayesha found the problem. The turn step said "repeat 3 times" instead of "repeat 1 time."

"We told it to turn three times!" Ayesha said. "The robot did exactly what we said."

Ben changed the 3 to a 1. They set the robot at the starting line and held their breath. The robot rolled forward, made one neat left turn, and stopped right on the paper line.

At the fair, a judge asked what they had learned. Ben pointed to the laptop. "Robots are not smart on their own," Ben said. "They follow every step, even the wrong ones. So you have to check your steps carefully."$q$, 'draft')
